import React, { useEffect, useState } from "react";
import { motion } from "framer-motion";
import StaffNavbar from "../components/StaffNavbar";

// ─── API BASE ────────────────────────────────────────────────────────────────
// Adjust this one constant if your XAMPP folder name ever changes.
const BASE = "http://localhost/GitHub/Capstone--Development";

export default function Products() {

  const [products, setProducts]           = useState([]);
  const [loading, setLoading]             = useState(true);
  const [fetchError, setFetchError]       = useState(null);   // ← NEW: surface errors

  const [selectedProduct, setSelectedProduct] = useState(null);
  const [qty, setQty]                     = useState("");
  const [updateError, setUpdateError]     = useState(null);   // ← NEW: modal-level error

  /* =========================
     FETCH PRODUCTS
  ========================= */
  const fetchProducts = () => {

    setLoading(true);
    setFetchError(null);

    fetch(`${BASE}/staff/api_products.php?action=list`)
      .then(res => {
        if (!res.ok) throw new Error(`HTTP ${res.status}`);
        return res.json();
      })
      .then(data => {
        if (Array.isArray(data)) {
          setProducts(data);
        } else {
          // Backend returned an error object instead of an array
          setFetchError(data?.error || "Unexpected response from server.");
          setProducts([]);
        }
      })
      .catch(err => {
        setFetchError(`Could not reach the server: ${err.message}`);
        setProducts([]);
      })
      .finally(() => setLoading(false));

  };

  useEffect(() => {
    fetchProducts();
  }, []);

  /* =========================
     UPDATE STOCK
  ========================= */
  const updateStock = (type) => {

    setUpdateError(null);

    const parsed = Number(qty);

    // ── Validate before sending ──────────────────────────────────────────────
    if (!selectedProduct)           return;
    if (!qty || isNaN(parsed) || parsed <= 0) {
      setUpdateError("Please enter a valid quantity greater than 0.");
      return;
    }

    fetch(`${BASE}/staff/api_update_stock.php`, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({
        id:   selectedProduct.id,
        qty:  parsed,
        type
      })
    })
      .then(res => {
        if (!res.ok) throw new Error(`HTTP ${res.status}`);
        return res.json();
      })
      .then(data => {
        if (data.status === "success") {
          fetchProducts();
          setSelectedProduct(null);
          setQty("");
          setUpdateError(null);
        } else {
          setUpdateError(data.message || "Update failed. Please try again.");
        }
      })
      .catch(err => {
        setUpdateError(`Server error: ${err.message}`);
      });

  };

  /* =========================
     STOCK STATUS COLOR
  ========================= */
  const getStockColor = (stock) => {
    const s = stock ?? 0;
    if (s <= 0)  return "text-red-600";
    if (s <= 5)  return "text-yellow-600";
    return "text-green-600";
  };

  /* =========================
     RENDER
  ========================= */
  return (

    <div className="bg-[#fafafa] min-h-screen">

      {/* NAVBAR */}
      <StaffNavbar />

      {/* PAGE WRAPPER */}
      <div className="p-8 xl:p-10 pt-24">

        {/* HEADER */}
        <div className="mb-10">
          <p className="text-[10px] uppercase tracking-[0.3em] text-gray-400">
            Inventory Control
          </p>
          <h1 className="text-4xl font-bold">Products Management</h1>
        </div>

        {/* ── STATES ── */}
        {loading && (
          <p className="text-gray-400">Loading products…</p>
        )}

        {/* NEW: visible fetch error */}
        {!loading && fetchError && (
          <div className="bg-red-50 border border-red-200 text-red-700 rounded-xl p-4 mb-6">
            <p className="font-semibold">Failed to load products</p>
            <p className="text-sm mt-1">{fetchError}</p>
            <button
              onClick={fetchProducts}
              className="mt-3 text-xs underline"
            >
              Try again
            </button>
          </div>
        )}

        {!loading && !fetchError && products.length === 0 && (
          <p className="text-gray-400">No products found in the database.</p>
        )}

        {/* PRODUCT GRID */}
        {!loading && !fetchError && products.length > 0 && (

          <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-6">

            {products.map(product => (

              <motion.div
                key={product.id}
                whileHover={{ y: -5 }}
                className="bg-white rounded-2xl shadow-md overflow-hidden border border-gray-100"
              >

                {/* IMAGE */}
                <div className="h-40 overflow-hidden bg-gray-100">
                  <img
                    src={`${BASE}/uploads/${product.image}`}
                    className="w-full h-full object-cover"
                    alt={product.name}
                    onError={e => { e.target.style.display = "none"; }} // hide broken images
                  />
                </div>

                {/* CONTENT */}
                <div className="p-5">

                  <h2 className="font-bold text-lg">{product.name}</h2>

                  <p className="text-xs text-gray-400 mb-2">{product.category}</p>

                  {/* STOCK */}
                  <p className="text-sm mb-3">
                    Stock:
                    <span className={`font-bold ml-2 ${getStockColor(product.stock)}`}>
                      {product.stock ?? 0}
                    </span>
                  </p>

                  {/* BUTTON */}
                  <button
                    onClick={() => {
                      setSelectedProduct(product);
                      setQty("");
                      setUpdateError(null);
                    }}
                    className="w-full bg-black text-white text-xs py-2 rounded-lg hover:bg-gray-800"
                  >
                    Manage Stock
                  </button>

                </div>

              </motion.div>

            ))}

          </div>

        )}

        {/* =========================
            STOCK MODAL
        ========================= */}
        {selectedProduct && (

          <div className="fixed inset-0 bg-black/40 flex items-center justify-center z-50">

            <div className="bg-white w-[350px] rounded-2xl p-6 shadow-xl">

              <h2 className="text-lg font-bold mb-2">
                {selectedProduct.name}
              </h2>

              <p className="text-sm text-gray-500 mb-4">
                Current Stock:&nbsp;
                <span className={`font-bold ${getStockColor(selectedProduct.stock)}`}>
                  {selectedProduct.stock ?? 0}
                </span>
              </p>

              {/* INPUT */}
              <input
                type="number"
                min="1"
                value={qty}
                onChange={e => {
                  setQty(e.target.value);
                  setUpdateError(null);
                }}
                placeholder="Enter quantity"
                className="w-full border p-2 rounded-lg mb-3"
              />

              {/* NEW: inline error */}
              {updateError && (
                <p className="text-red-500 text-xs mb-3">{updateError}</p>
              )}

              {/* ACTIONS */}
              <div className="flex gap-2">

                <button
                  onClick={() => updateStock("in")}
                  className="flex-1 bg-green-500 text-white py-2 rounded-lg text-sm hover:bg-green-600"
                >
                  Stock In
                </button>

                <button
                  onClick={() => updateStock("out")}
                  className="flex-1 bg-red-500 text-white py-2 rounded-lg text-sm hover:bg-red-600"
                >
                  Stock Out
                </button>

              </div>

              {/* CLOSE */}
              <button
                onClick={() => {
                  setSelectedProduct(null);
                  setQty("");
                  setUpdateError(null);
                }}
                className="mt-3 w-full text-xs text-gray-500 hover:text-gray-700"
              >
                Cancel
              </button>

            </div>

          </div>

        )}

      </div>

    </div>

  );

}
